    if best and best ~= cur and (not U.eqAt or os.clock() - U.eqAt > 3) then
        U.eqAt = os.clock()
        M.inv("EquipTool", best)
    end
end
function U.tick()
    U.equipBest()
    local list = U.list()
    table.sort(list, function(a, b) return a.cost < b.cost end)
    for _, e in ipairs(list) do
        if not RUNNING then return end
        if M.spendable() < e.cost then return end
        local ok, msg
        if e.kind == "up" then ok, msg = M.inv("BuyUpgrade", e.arg)
        else ok, msg = M.inv("BuyItemUpgrade", e.arg) end
        if ok then S.bought += 1 else U.fails[e.key] = os.clock() + 6 LOG("buy refused", e.key, msg) end
    end
end
local B = { fails = {}, placedAt = 0 }
function B.prompt(inst)
    return inst and inst:FindFirstChildWhichIsA("ProximityPrompt", true)
end
function B.buyVia(key, pr, mode, cost)
    if B.fails[key] and os.clock() < B.fails[key] then return end
    if J.keys[key] then return end
    if M.spendable() < cost or not U.allowed(cost) then return end
    local p = M.promptPos(pr)
    if not p or not M.inRing(p, 6) then return end
    J.push(key, function()
        if M.spendable() < cost or not pr.Parent then return end
        S.task = __T["Buying "] .. tostring(pr.ObjectText)
        if not M.near(p, 5) then B.fails[key] = os.clock() + 30 return end
        local ok, msg = true, nil
        if mode == "inspect" then
            ok, msg = M.inv("InspectBuy", pr)
        else
            M.press(pr)
            task.wait(0.8)
        end
        LOG("base", key, tostring(ok), tostring(msg))
        if ok then S.bought += 1 else B.fails[key] = os.clock() + 15 end
    end)
end
function B.lockedPrompt(pr)
    return pr == nil or pr:GetAttribute("Locked") == true or pr.ActionText == "Locked" or not pr.Enabled
end
function B.tick()
    if not IS_MATCH then return end
    local base = Workspace:FindFirstChild("Map") and Workspace.Map:FindFirstChild("Base")
    if not base then return end
    if on("b_solar") then
        local farm = base:FindFirstChild("SolarFarm")
        for i = 1, 5 do
            local slot = farm and farm:FindFirstChild("Slot" .. i)
            local pr = slot and B.prompt(slot)
            if pr and not B.lockedPrompt(pr) then
                local c = M.price(pr)
                if c then B.buyVia("solar" .. i, pr, "inspect", c) break end
            end
        end
    end
    if on("b_veh") then
        for _, bay in ipairs(CollectionService:GetTagged("VehicleBay")) do
            local holder = bay:FindFirstChild("PromptPart")
            local pr = holder and holder:FindFirstChild("Prompt")
            local vk = pr and pr:GetAttribute("VehicleKey")
            if vk and picked("b_vehlist", vk) and not B.lockedPrompt(pr) then
                local c = M.price(pr)
                if c and pr.ActionText:find("^Buy %$") then B.buyVia("veh" .. vk, pr, "inspect", c) end
            end
        end
    end
    if on("b_bots") then
        for _, tag in ipairs({ "RobotDock", "DronePad" }) do
            for _, m in ipairs(CollectionService:GetTagged(tag)) do
                local pr = B.prompt(m)
                if pr and not B.lockedPrompt(pr) then
                    local c = M.price(pr)
                    if c then B.buyVia("bot" .. tag, pr, "inspect", c) end
                end
            end
        end
    end
    if on("b_build") then
        for _, m in ipairs(CollectionService:GetTagged("Building")) do
            local kind = m:GetAttribute("BuildingKind")
            if kind and picked("b_buildlist", kind) and m:GetAttribute("BuildingBought") ~= true then
                local pr = m:FindFirstChild("BuildingPrompt", true)
                local c = pr and M.price(pr)
                if c then B.buyVia("bld" .. kind, pr, "press", c) end
            end
        end
    end
    if on("b_land") then
        for _, m in ipairs(CollectionService:GetTagged("Landmark")) do
            if m:GetAttribute("LandmarkReady") == true and m:GetAttribute("LandmarkLit") ~= true then
                local pr = B.prompt(m)
                local c = pr and M.price(pr)
                if c and pr.Enabled then B.buyVia("lm" .. m:GetFullName() .. tostring(m:GetPivot().Position), pr, "press", c) end
            end
        end
    end
    if on("b_guard") and Workspace:FindFirstChild("MoonGuards") then
        for _, m in ipairs(Workspace.MoonGuards:GetChildren()) do
            local pr = m:FindFirstChild("GuardHirePrompt", true)
            if pr and pr.Enabled then
                local c = pr:GetAttribute("Price") or M.price(pr)
                local key = "gd" .. m.Name
                if type(c) == "number" and M.spendable() >= c and U.allowed(c) and not (B.fails[key] and os.clock() < B.fails[key]) then
                    B.buyVia(key, pr, "press", c)
                    B.fails[key] = os.clock() + 10
                    break
                end
            end
        end
    end
    if on("b_belts") and Workspace:FindFirstChild("Belts") then
        for port = 1, 5 do
            local sign = Workspace.Belts:FindFirstChild("LaneSign" .. port)
            local pr = sign and sign:FindFirstChild("Prompt", true)
            local c = pr and pr.Enabled and M.price(pr)
            local p = c and M.promptPos(pr)
            local key = "belt" .. port
            B.beltDone = B.beltDone or {}
            if c and p and not B.beltDone[port] and M.spendable() >= c and U.allowed(c) and M.inRing(p, 6) and not (B.fails[key] and os.clock() < B.fails[key]) then
                J.push(key, function()
                    S.task = __T["Buying conveyor"]
                    if not M.near(p, 4) then return end
                    local lane = Cfg.Belts and Cfg.Belts.Lanes and Cfg.Belts.Lanes[port]
                    local ok, msg = M.inv("PlaceBelt", port, lane and lane.way or 1)
                    LOG("belt", port, tostring(ok), tostring(msg))
                    if ok then S.bought += 1 else
                        B.fails[key] = os.clock() + 30
                        if type(msg) == "string" and msg:find("as far as") then B.beltDone[port] = true end
                    end
                end)
                break
            end
        end
    end
    if on("b_garden") and Cfg.Garden and M.spendable() > 0 then
        for _, m in ipairs(CollectionService:GetTagged("Building")) do
            if m:GetAttribute("BuildingKind") == "OxygenGarden" and m:GetAttribute("BuildingBought") == true then
                local pr = m:FindFirstChild("GardenPrompt", true)
                local c = pr and M.price(pr)
                local p = M.promptPos(pr)
                if c and p and M.spendable() >= c and M.inRing(p, 6) and not (B.fails.garden and os.clock() < B.fails.garden) then
                    J.push("garden", function()
                        S.task = __T["Buying plant"]
                        if not M.near(p, 4) then return end
                        local ok = M.inv("BuyGardenPlant")
                        if ok then S.bought += 1 else B.fails.garden = os.clock() + 15 end
                    end)
                end
            end
        end
    end
    if on("b_work") then
        for _, m in ipairs(CollectionService:GetTagged("Building")) do
            local offers = m:GetAttribute("WorkshopOffers")
            if type(offers) == "string" and m:GetAttribute("BuildingBought") == true then
                for key in offers:gmatch("[^,]+") do
                    local row
                    for _, it in ipairs((Cfg.Workshop and Cfg.Workshop.items) or {}) do if it.key == key then row = it end end
                    if row and picked("b_worklist", key) and M.n("WorkshopStock_" .. key) > 0 and M.spendable() >= row.cost and not (B.fails["w" .. key] and os.clock() < B.fails["w" .. key]) then
                        local p = m:GetPivot().Position
                        J.push("wk" .. key, function()
                            S.task = __T["Buying "] .. key
                            if not M.near(p, 8) then return end
                            local ok = M.inv("BuyWorkshopOffer", key)
                            if ok then S.bought += 1 else B.fails["w" .. key] = os.clock() + 20 end
                        end)
                    end
                end
            end
        end
    end
    if on("b_place") then
        local list = lp:GetAttribute("PlaceableBots")
        if type(list) == "string" and list ~= "" and os.clock() - B.placedAt > 2 then
            B.placedAt = os.clock()
            local key = list:match("[^,]+")
            J.push("place", function()
                S.task = __T["Placing "] .. tostring(key)
                local cell = F.pickChunk()
                if not cell then return end
                local avoid = Cfg.Robots
                local g = Vector3.new(cell.X, M.ground(cell.X, cell.Z) - 3.4, cell.Z)
                if avoid and avoid.avoidMin and g.X >= avoid.avoidMin.X and g.X <= avoid.avoidMax.X and g.Z >= avoid.avoidMin.Y and g.Z <= avoid.avoidMax.Y then return end
                M.near(g, 8)
                local ok, msg = M.inv("PlaceBot", key, g)
                LOG("place", key, tostring(ok), tostring(msg))
                if ok then S.placed += 1 end
            end)
        end
    end
end
local E = { arcadeAt = 0 }
function E.kind() return Workspace:GetAttribute("EventKind") end
function E.ok() return Workspace:GetAttribute("EventStage") == "active" or Workspace:GetAttribute("EventStage") == nil end
function E.crates()
    local fd = Workspace:FindFirstChild("ExpressDeliveryCrates")
    if not fd then return end
    for _, c in ipairs(fd:GetChildren()) do
        if not RUNNING or not c.Parent then break end
        local pr = c:FindFirstChildWhichIsA("ProximityPrompt", true)
        local p = pr and pr.Enabled and M.promptPos(pr)
        if p and M.inRing(p, 4) then
            S.task = __T["Opening crates"]
            M.near(p, 5)
            M.press(pr)
            task.wait(0.7)
            S.crates += 1
        end
    end
end
function E.arcadeGame(cab)
    local g = cab:GetAttribute("Game")
    return type(g) == "string" and g or "MeteorBlaster"
end
function E.arcade()
    if E.run then return end
    local cab
    for _, c in ipairs(CollectionService:GetTagged("ArcadeCabinet")) do
        if c:IsDescendantOf(Workspace) then cab = cab or c end
    end
    if not cab then return end
    local game_ = E.arcadeGame(cab)
    local row = Cfg.Arcade and Cfg.Arcade.games and Cfg.Arcade.games[game_]
    if not row then return end
    local p = cab:IsA("Model") and cab:GetPivot().Position or cab.Position
    S.task = "Arcade"
    if not M.near(p, 4) then return end
    local ok, msg, tok = M.inv("ArcadeStart", game_)
    LOG("arcade start", game_, tostring(ok), tostring(msg), tostring(tok))
    if not ok then E.arcadeAt = os.clock() + 4 return end
    local cap = math.max(M.n("ArcadeCap"), 1)
    local need = cap / row.cashPerPoint
    local secs = Cfg.Arcade.fullPaySeconds
    local ends = Workspace:GetAttribute("EventEndsAt")
    if type(ends) == "number" then secs = math.clamp(ends - M.now() - 1.5, Cfg.Arcade.minSeconds + 0.5, secs) end
    E.run = { game = game_, tok = tok, row = row, t0 = os.clock(), secs = secs, need = need, cap = cap, cab = p }
end
function E.arcadeFinish()
    local a = E.run
    if not a or a.ending or os.clock() - a.t0 < a.secs then return end
    a.ending = true
    task.spawn(function()
        local el = os.clock() - a.t0
        local score = math.floor(math.min(a.need * 1.02, (a.row.burstPoints + el * a.row.maxPointsPerSecond) * 0.95))
        local c0 = M.n("Cash")
        local ok, text = M.inv("ArcadeEnd", a.game, score, a.tok)
        LOG("arcade end", a.game, score, string.format("%.1fs", el), tostring(ok), tostring(text), "cap", a.cap, "cash", c0)
        if ok then S.arcade += 1 end
        E.run = nil
        E.arcadeAt = os.clock() + Cfg.Arcade.startCooldown + 0.3
    end)
end
function E.merchantWant()
    local m = Workspace:FindFirstChild("MeteorMerchant")
    if not m or m:GetAttribute("MerchantPhase") ~= "open" then return nil end
    local offers = m:GetAttribute("MerchantOffers")
    if type(offers) ~= "string" then return nil end
    local pool = {}
    local ev = Cfg.Events and Cfg.Events.MeteorMerchant
    for _, l in ipairs({ ev and ev.cashPool or {}, ev and ev.halloweenPool or {} }) do for _, r in ipairs(l) do pool[r.key] = r end end
    for key in offers:gmatch("[^,]+") do
        local r = pool[key]
        if r and picked("e_merch", key) and M.n("MerchantStock_" .. key) > 0 and M.spendable() >= r.cost and not (E.merchFail and E.merchFail[key]) then return key, m end
    end
    return nil
end
function E.merchant()
    local key, m = E.merchantWant()
    if not key then return end
    S.task = __T["Merchant"]
    M.near(m:GetPivot().Position, 10)
    local ok, msg = M.inv("BuyMerchantOffer", key)
    LOG("merchant", key, tostring(ok), tostring(msg))
    if ok then S.bought += 1 else E.merchFail = E.merchFail or {} E.merchFail[key] = true end
end
function E.shoot(folderName, wantKey)
    local fd = Workspace:FindFirstChild(folderName)
    if not fd then return false end
    local r = M.root()
    if not r then return false end
    local target, bd
    for _, a in ipairs(fd:GetChildren()) do
        local hp = a:IsA("Model") and a.PrimaryPart
        if hp and a:GetAttribute("AlienId") and a:GetAttribute("Poof") ~= true and (not wantKey or a:GetAttribute("KeyCarrier") == true) then
            local d = (hp.Position - r.Position).Magnitude
            if not bd or d < bd then target, bd = a, d end
        end
    end
    if not target then return false end
    local hp = target.PrimaryPart
    if lp:GetAttribute("HasRaygun") ~= true then return false end
    if lp:GetAttribute("RaygunOut") ~= true then M.fire("RaygunEquip", true) task.wait(0.2) end
    local inside = target:GetAttribute("Inside") == true
    if bd > (inside and 9 or 45) or (inside and math.abs(r.Position.Y - hp.Position.Y) > 3) then
        local dir = ((r.Position - hp.Position) * Vector3.new(1, 0, 1))
        dir = dir.Magnitude > 1 and dir.Unit or Vector3.new(0, 0, 1)
        local q = hp.Position + dir * (inside and 6 or 30)
        M.moving(Vector3.new(q.X, inside and hp.Position.Y or M.ground(q.X, q.Z), q.Z))
        task.wait(inside and 0.45 or 0.35)
        r = M.root()
        if not r then return true end
    end
    local head = r.Position + Vector3.new(0, 1.5, 0)
    local aim = hp.Position - head
    if aim.Magnitude > 0.1 then M.fire("RaygunFire", aim.Unit, target:GetAttribute("AlienId")) end
    task.wait(0.33)
    return true
end
function E.ufoWork()
    local u = Workspace:FindFirstChild("UfoRaid")
    if not u or u:GetAttribute("ChestOpened") == true then return false end
    local land = u:GetAttribute("LandAt")
    if type(land) == "number" and M.now() < land then return false end
    return true
end
function E.ufo()
    local t0 = os.clock()
    S.task = __T["UFO raid"]
    while RUNNING and os.clock() - t0 < 25 and E.ufoWork() and M.ready() do
        local u = Workspace:FindFirstChild("UfoRaid")
        local chest = u:FindFirstChild("Chest")
        local chestP = chest and chest:FindFirstChild("ChestPrompt", true)
        local loot = Workspace:FindFirstChild("UfoRaidLoot")
        local key = (loot and loot:FindFirstChild("UfoKey", true)) or Workspace:FindFirstChild("UfoKey", true)
        if u:GetAttribute("KeyFound") == true and chestP then
            local p = M.promptPos(chestP)
            if p then
                M.near(p, 4)
                M.press(chestP)
                task.wait(1)
                LOG("ufo chest", chestP.ActionText, tostring(u:GetAttribute("ChestOpened")))
                if u:GetAttribute("ChestOpened") == true then S.chests += 1 end
            else
                task.wait(0.3)
            end
        elseif key and key:IsA("Model") then
            local kp = key:FindFirstChildWhichIsA("ProximityPrompt", true)
            local p = kp and M.promptPos(kp) or key:GetPivot().Position
            M.near(p, 3)
            if kp then M.press(kp) end
            task.wait(0.5)
            LOG("ufo key", tostring(u:GetAttribute("KeyFound")))
        elseif not (E.shoot("UfoRaidAliens", true) or E.shoot("UfoRaidAliens", false)) then
            local q = u:GetPivot().Position
            local r = M.root()
            if r and (r.Position - q).Magnitude > 45 then
                M.near(q, 32)
                task.wait(0.8)
            else
                E.ufoFailAt = os.clock() + 6
                LOG("ufo idle hasRay", tostring(lp:GetAttribute("HasRaygun")), "left", tostring(u:GetAttribute("AliensLeft")))
                break
            end
        end
    end
    if lp:GetAttribute("RaygunOut") == true then M.fire("RaygunEquip", false) end
end
function E.raid()
    S.task = __T["Goblin raid"]
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 12 and E.kind() == "GoblinRaid" and M.ready() do
        if not E.shoot("GoblinRaid", false) then
            E.raidFailAt = os.clock() + 4
            break
        end
    end
    if lp:GetAttribute("RaygunOut") == true then M.fire("RaygunEquip", false) end
end
function E.halloween()
    if not Cfg.Halloween or (Cfg.Halloween.endsAt and os.time() > Cfg.Halloween.endsAt) then return end
    local ok, sh = pcall(function() return Workspace.Map.Halloween.HalloweenShop end)
    if not ok or not sh then return end
    local p = B.prompt(sh) and M.promptPos(B.prompt(sh))
    for _, r in ipairs(Cfg.Halloween.Shop or {}) do
        if picked("e_hshop", r.key) and M.n("Candy") >= r.cost and not (E.hFail and E.hFail[r.key] and os.clock() < E.hFail[r.key]) then
            J.push("hshop" .. r.key, function()
                S.task = __T["Halloween shop"]
                if p then M.near(p, 5) end
                local good, msg = M.inv("HalloweenShopBuy", r.key)
                LOG("hshop", r.key, tostring(good), tostring(msg))
                E.hFail = E.hFail or {}
                E.hFail[r.key] = os.clock() + (good and 2 or 30)
            end)
        end
    end
end
function E.repair()
    if not (on("f_clean") or on("f_sell") or on("e_raid")) then return end
    local ok, rec = pcall(function() return Workspace.Map.Base.Recycler end)
    if not ok or not rec then return end
    local ju = rec:GetAttribute("JammedUntil")
    if type(ju) ~= "number" or ju <= M.now() then return end
    for _, d in ipairs(rec:GetDescendants()) do
        if d:IsA("ProximityPrompt") and (d.ActionText:lower():find("repair") or d.ActionText:lower():find("fix")) and d.Enabled then
            local p = M.promptPos(d)
            J.push("repair", function()
                S.task = __T["Repairing converter"]
                if p then M.near(p, 4) end
                M.press(d)
                local t = os.clock()
                while os.clock() - t < 10 and d.Parent and (rec:GetAttribute("JammedUntil") or 0) > M.now() do task.wait(0.2) end
                LOG("repair", tostring(rec:GetAttribute("JammedUntil")))
            end)
            return
        end
    end
end
function E.tick()
    if not IS_MATCH then return end
    local k = E.kind()
    if on("e_crates") and Workspace:FindFirstChild("ExpressDeliveryCrates") and #Workspace.ExpressDeliveryCrates:GetChildren() > 0 then J.push("crates", E.crates) end
    if E.run then E.arcadeFinish() end
    if on("e_arcade") and k == "Arcade" and not E.run and os.clock() >= E.arcadeAt and Workspace:GetAttribute("EventStage") ~= "ending" then J.push("arcade", E.arcade) end
    if on("e_merchant") and E.merchantWant() then J.push("merchant", E.merchant) end
    if on("e_ufo") and E.ufoWork() and os.clock() >= (E.ufoFailAt or 0) then J.push("ufo", E.ufo) end
    if on("e_raid") and k == "GoblinRaid" and os.clock() >= (E.raidFailAt or 0) then J.push("raid", E.raid) end
    E.repair()
    if on("e_hshop_on") then E.halloween() end
end
local LB = { codesDone = false, startAt = 0, startDone = false }
function LB.codes()
    if LB.codesDone or not IS_LOBBY or not on("l_codes") then return end
    LB.codesDone = true
    local list = (Cfg.Codes and Cfg.Codes.List) or {}
    for code, row in pairs(list) do
        if not (row.expires and os.time() > row.expires) then
            local ok, msg = M.inv("RedeemCode", code)
            LOG("code", code, tostring(ok), tostring(msg))
            if ok then notify(tostring(msg or (__T["Redeemed "] .. code))) end
            task.wait(2.2)
        end
    end
end
function LB.group()
    if not IS_LOBBY or not on("l_group") or LB.groupDone or lp:GetAttribute("GroupRewardClaimed") == true then return end
    LB.groupDone = true
    local ok, msg = M.inv("ClaimGroupReward")
    LOG("group", tostring(ok), tostring(msg))
    notify(tostring(msg or (ok and __T["Claimed"] or __T["Join the group first"])))
end
function LB.perks()
    if not IS_LOBBY or not on("l_perks") or not Cfg.Perks then return end
    local list = {}
    for _, p in ipairs(Cfg.Perks.List or {}) do
        if picked("l_perklist", p.key) then
            local lv = M.n("Perk_" .. p.key)
            local c = p.costs and p.costs[lv + 1]
            if lv < (p.maxLevel or 0) and c and not (LB.fail and LB.fail[p.key] and os.clock() < LB.fail[p.key]) then list[#list + 1] = { key = p.key, cost = c } end
        end
    end
    table.sort(list, function(a, b) return a.cost < b.cost end)
    for _, e in ipairs(list) do
        if M.n("Moonstones") < e.cost then return end
        local ok, msg = M.inv("BuyPerk", e.key)
        LOG("perk", e.key, tostring(ok), tostring(msg))
        if not ok then LB.fail = LB.fail or {} LB.fail[e.key] = os.clock() + 20 end
    end
end
function LB.classes()
    if not IS_LOBBY or not Cfg.Classes then return end
    if on("l_class") then
        for _, c in ipairs(Cfg.Classes.List or {}) do
            if picked("l_classlist", c.key) and lp:GetAttribute("Class_" .. c.key) ~= true and (c.cost or 0) > 0 and c.key ~= "NightShift" and M.n("Moonstones") >= c.cost and not (LB.cf and LB.cf[c.key] and os.clock() < LB.cf[c.key]) then
                local ok, msg = M.inv("BuyClass", c.key)
                LOG("class", c.key, tostring(ok), tostring(msg))
                LB.cf = LB.cf or {}
                LB.cf[c.key] = os.clock() + 20
            end
        end
    end
    local eq = val("l_equip", "Keep")
    if eq ~= "Keep" and lp:GetAttribute("Class") ~= eq and lp:GetAttribute("Class_" .. eq) == true and (not LB.eqAt or os.clock() - LB.eqAt > 4) then
        LB.eqAt = os.clock()
        M.inv("EquipClass", eq)
    end
end
function LB.start()
    if not IS_LOBBY or not on("l_start") or LB.startDone or os.clock() < LB.startAt then return end
    if lp:GetAttribute("DataLoaded") ~= true then return end
    local pad = Workspace:FindFirstChild("Lobby") and Workspace.Lobby:FindFirstChild("Pads") and Workspace.Lobby.Pads:FindFirstChild("PadSolo")
    local zone = pad and pad:FindFirstChild("Zone")
    if not zone then return end
    LB.startAt = os.clock() + 8
    local got = false
    local c = D.Rm.PadPrompt.OnClientEvent:Connect(function(id) if id then got = true end end)
    M.fire("LeavePad")
    M.moving(Vector3.new(0, 4, 20))
    task.wait(0.6)
    M.moving(zone.Position + Vector3.new(0, 3.2, 0))
    local t = os.clock()
    while not got and os.clock() - t < 5 do task.wait(0.1) end
    c:Disconnect()
    if not got then return end
    local newMoon = val("l_startmode", "Continue Saved Moon") == "New Moon"
    local ok, msg = M.inv("CreateParty", 1, false, true, newMoon, "Moon")
    LOG("start", tostring(ok), tostring(msg))
    if ok then LB.startDone = true notify(__T["Launching"]) end
end
function LB.replay()
    if not IS_MATCH or not on("l_replay") or M.kicked() then return end
    local pod = Workspace:GetAttribute("PodState")
    if pod == "open" and lp:GetAttribute("AboardPod") ~= true and M.alive() then
        if not LB.podAt or os.clock() - LB.podAt > 3 then
            LB.podAt = os.clock()
            J.push("pod", function()
                local site = Workspace:GetAttribute("HatchSite")
                local p = typeof(site) == "CFrame" and site.Position
                local m = Workspace:FindFirstChild("MoonHatch")
                if not p and m then p = m:GetPivot().Position end
                if p then
                    S.task = __T["Boarding pod"]
                    M.moving(p + Vector3.new(0, 3.5, 0))
                    local pr = m and m:FindFirstChildWhichIsA("ProximityPrompt", true)
                    task.wait(0.6)
                    if pr then M.press(pr) end
                    task.wait(1.5)
                    LOG("pod", tostring(lp:GetAttribute("AboardPod")))
                end
            end)
        end
    end
    if LB.results and lp:GetAttribute("EndChoice") == nil and lp:GetAttribute("InCutscene") ~= true and (pod == nil or pod == "gone" or lp:GetAttribute("AboardPod") == true) then
        if not LB.endAt or os.clock() - LB.endAt > 5 then
            LB.endAt = os.clock()
            local ok, msg = M.inv("EndChoice", val("l_replaymode", "Play Again") == "Play Again" and "again" or "lobby")
            LOG("end choice", tostring(ok), tostring(msg))
        end
    end
end
