local P = { vm = {} }
function P.hideVm(m, hide)
    if m.Name ~= "ToolViewModel" and m.Name ~= "LeftHandViewModel" then return end
    for _, d in ipairs(m:GetDescendants()) do
        if d:IsA("BasePart") then d.LocalTransparencyModifier = hide and 1 or 0
        elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") then d.Enabled = not hide end
    end
end
function P.applyCam()
    if not P.tp then return end
    P.minWas = P.minWas or lp.CameraMinZoomDistance
    if lp:GetAttribute("InCutscene") == true or lp:GetAttribute("Driving") ~= nil then return end
    if lp.CameraMode ~= Enum.CameraMode.Classic then lp.CameraMode = Enum.CameraMode.Classic end
    lp.CameraMaxZoomDistance = 128
    lp.CameraMinZoomDistance = math.clamp(val("p_zoom", 14), 4, 60)
end
function P.setThird(v)
    P.tp = v
    local cam = Workspace.CurrentCamera
    if P.camConn then P.camConn:Disconnect() P.camConn = nil end
    if v then
        P.applyCam()
        if cam then
            for _, m in ipairs(cam:GetChildren()) do P.hideVm(m, true) end
            P.camConn = cam.ChildAdded:Connect(function(m) task.defer(function() if P.tp then P.hideVm(m, true) end end) end)
        end
    else
        if cam then for _, m in ipairs(cam:GetChildren()) do P.hideVm(m, false) end end
        lp.CameraMinZoomDistance = P.minWas or 0.5
        P.minWas = nil
        if IS_MATCH and lp:GetAttribute("InCutscene") ~= true and lp:GetAttribute("Driving") == nil then lp.CameraMode = Enum.CameraMode.LockFirstPerson end
    end
end
function P.setFx(v)
    if v then
        if P.fxWas == nil then P.fxWas = lp:GetAttribute("Setting_Vfx") ~= false end
        M.fire("SetSetting", "vfx", false)
    elseif P.fxWas ~= nil then
        M.fire("SetSetting", "vfx", P.fxWas)
        P.fxWas = nil
    end
end
P.ghost = {}
function P.noclipOff()
    for part, was in pairs(P.ghost) do if part.Parent then part.CanCollide = was end end
    P.ghost = {}
end
function P.setFace(v)
    pcall(function()
        local us = UserSettings():GetService("UserGameSettings")
        if v then
            P.rotWas = P.rotWas or us.RotationType
            us.RotationType = Enum.RotationType.CameraRelative
        elseif P.rotWas then
            us.RotationType = P.rotWas
            P.rotWas = nil
        end
    end)
end
