        local row = Cfg.Upgrades and Cfg.Upgrades.Boots and Cfg.Upgrades.Boots.values[boots]
        h.WalkSpeed = math.max(row or 0, P.wsWas)
        P.wsWas = nil
    end
    if on("p_jump") then
        local v = val("p_jump_v", 20)
        if h.JumpHeight ~= v then h.JumpHeight = v end
    end
end))
