task.spawn(function()
    while RUNNING do
        pcall(function()
            local cash = M.n("Cash")
            local now = os.clock()
            S.earned = S.earned or 0
            if S.lastCash and cash > S.lastCash then S.earned += cash - S.lastCash end
            S.lastCash = cash
            local mins = math.max((now - S.t0) / 60, 0.25)
            local _, r = M.ring()
            setText(UI.s1, string.format(__T["Cash %s · +%s/min"], M.cash(cash), M.cash(S.earned / mins)))
            setText(UI.s2, string.format(__T["Tank %s / %s · Tool %s"], M.count(M.n("TankDust")), M.count(M.n("TankCapacity")), tostring(lp:GetAttribute("ToolKey") or "-")))
            local share = Workspace:GetAttribute("ZoneGateShare")
            setText(UI.s3, type(share) == "number" and string.format(__T["Ring %s · %.1f%% clean"], tostring(Workspace:GetAttribute("ZoneGateRing") or "-"), share * 100) or (r == math.huge and __T["All rings open"] or ""))
            setText(UI.s4, __T["Doing: "] .. S.task)
            setText(UI.s5, string.format(__T["Sold %d · Bought %d · Arcade %d · Crates %d"], S.sold, S.bought, S.arcade, S.crates))
            local k = Workspace:GetAttribute("EventKind")
            local msg = (os.clock() - S.gmsgAt < 8 and S.gmsg ~= "") and S.gmsg or ""
            setText(UI.ev, (k and (__T["Event: "] .. tostring(Workspace:GetAttribute("EventTitle") or k)) or __T["No event"]) .. (msg ~= "" and ("\n" .. msg) or ""))
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    do
        local name, ok, err = SaveManager:GetAutoloadConfig()
        local loaded = false
        if ok and not err then
            loaded = SaveManager:Load(name) == true
            if not loaded then SaveManager.Library:Notify("Autoload config not found, using last settings") end
        end
        if not loaded and isfile and isfile("COMBO_WICK_MOON/settings/auto.json") then SaveManager:Load("auto") end
    end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "f_pause" or k == "l_startmode" or k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
notify(__T["Loaded"])

end
